// ---- SERVER (Tier 4+) ----
const TagEvent = Remote.event('Tag');          // client → server when they think they touched someone
const UpdateIt = Remote.event('UpdateIt');      // server → each client to announce who is It
const Boost = Remote.event('Boost');

let itPlayer = null;   // the player who is currently “It”

// When a player joins, give them a default title and, if no one is It yet, make them It
players.onJoin(p => {
    p.title = '';                     // clear any old title
    p.setAttribute('isIt', false);   // our own flag (client can read it)

    // First player becomes “It”
    if (!itPlayer) {
        setIt(p);
    }
});

Boost.onServerEvent(async function(player) {
  player.speed = 2;
  await wait(2000);
  player.speed = 1;
})

// Helper – mark a player as “It” and broadcast the change
function setIt(p) {
    if (itPlayer) {
        // clear old It
        itPlayer.setAttribute('isIt', false);
        itPlayer.title = '';
    }
    itPlayer = p;
    itPlayer.setAttribute('isIt', true);
    itPlayer.title = 'It!';

    // Tell every client who is It (they update the UI)
    UpdateIt.fireAllClients(itPlayer.name);
}

// When a client tells us they touched someone, verify and switch It
TagEvent.onServerEvent((player, touchedName) => {
    // safety – only the real player who sent the event is trusted
    const target = players.get(touchedName);
    if (!target) return;                     // no such player
    if (player !== itPlayer) return;        // only the current It can tag

    // Transfer It status
    setIt(target);
});

// ---- CLIENT (runs in each browser) ----
const TagEvent   = Remote.event('Tag');
const UpdateIt   = Remote.event('UpdateIt');
const Boost = Remote.event('Boost')

let myName = localPlayer.name;

// UI – simple text badge at the top
ui.text('tagStatus', '', { anchor: 'top', y: 12, size: 20, color: '#ff0000' });

// Listen for server announcing who is It
UpdateIt.onClientEvent(itName => {
    const isIt = (itName === myName);
    ui.text('tagStatus',
        isIt ? 'You are IT! (press Space to tag)' : `${itName} is IT`,
        { anchor: 'top', y: 12, size: 20, color: isIt ? '#ff0000' : '#000000' });
});

// When you are It, you can “tag” another player by pressing Space while near them
input.onKeyDown(key => {
    if (key === 'q') Boost.fireServer();
    if (key !== ' ') return;               // only react to Space
    if (!localPlayer.getAttribute('isIt')) return; // not It → ignore

    // Find the closest other player within a small radius (e.g., 30 units)
    let closest = null, dist = 30;
    for (const p of players.all()) {
        if (p.name === myName) continue;   // skip yourself
        const d = Math.hypot(p.x - localPlayer.x, p.y - localPlayer.y);
        if (d < dist) { closest = p; dist = d; }
    }
    if (closest) {
        // Tell the server we think we touched this player
        TagEvent.fireServer(closest.name);
    }
});

ui.text('boost', 'Press Q to get a speed boost', { anchor: 'center', y: -200});
